  'STEP 2' => 'ШАГ 2',
  'Match Spread sheet data according to instruction' => 'Сопоставьте данные электронной таблицы в соответствии с инструкцией.',
  'STEP 3' => 'ШАГ 3',
  'Validate data and complete import' => 'Проверка данных и завершение импорта',
  'Instructions' => 'Инструкции',
  '1. Download the format file and fill it with proper data.' => '1. Загрузите файл формата и заполните его соответствующими данными.',
  '2. You can download the example file to understand how the data must be filled.' => '2. Вы можете скачать файл примера, чтобы понять, как необходимо заполнять данные.',
  '4. After uploading stores you need to edit them and set stores`s logo and cover.' => '4. После загрузки магазинов их необходимо отредактировать и установить логотип и обложку магазина.',
  '5. You can get module id and  zone id from their list, please input the right ids.' => '5. Вы можете получить идентификатор модуля и идентификатор зоны из их списка, пожалуйста, введите правильные идентификаторы.',
  '6. For delivery time the format is "from-to type" for example: "30-40 min". Also you can use days or hours as type. Please be carefull about this format or leave this field empty.' => '6. Время доставки имеет формат от-до например: 30-40 мин. Также вы можете использовать дни или часы в качестве типа. Пожалуйста, будьте осторожны с этим форматом или оставьте это поле пустым.',
  '7. You can upload your store images in store folder from gallery, and copy image`s path.' => '7. Вы можете загрузить изображения своего магазина в папку магазина из галереи и скопировать путь к изображению.',
  '8. Default password for store is 12345678.' => '8. Пароль для магазина по умолчанию: 12345678.',
  '9. Latitude must be a number between -90 to 90 and Longitude must a number between -180 to 180. Otherwise it will create server error' => '9. Широта должна быть числом от -90 до 90, а долгота - числом от -180 до 180. В противном случае возникнет ошибка сервера.',
