  'Go to Firebase Console' => 'Перейдите в консоль Firebase',
  'Open your web browser and go to the Firebase Console' => 'Откройте веб-браузер и перейдите в консоль Firebase.',
  '(https://console.firebase.google.com/)' => '(https://console.firebase.google.com/)',
  'Select the project for which you want to configure FCM from the Firebase Console dashboard.' => 'Выберите проект, для которого вы хотите настроить FCM, на панели управления Firebase Console.',
  'Navigate to Project Settings' => 'Перейдите к настройкам проекта.',
  'In the left-hand menu, click on the "Settings" gear icon, and then select "Project settings" from the dropdown.' => 'В меню слева нажмите на значок шестеренки «Настройки», а затем выберите «Настройки проекта» в раскрывающемся списке.',
  'In the Project settings page, click on the "Cloud Messaging" tab from the top menu.' => 'На странице настроек проекта нажмите вкладку Cloud Messaging в верхнем меню.',
  'Obtain All The Information Asked!' => 'Получите всю запрашиваемую информацию!',
  'In the Firebase Project settings page, click on the "General" tab from the top menu.' => 'На странице настроек проекта Firebase нажмите вкладку «Общие» в верхнем меню.',
  'Under the "Your apps" section, click on the "Web" app for which you want to configure FCM.' => 'В разделе «Ваши приложения» выберите веб-приложение, для которого вы хотите настроить FCM.',
  'Then Obtain API Key, FCM Project ID, Auth Domain, Storage Bucket, Messaging Sender ID.' => 'Затем получите API-ключ. Идентификатор проекта FCM. Идентификатор отправителя сообщений в сегменте хранилища домена аутентификации.',
  'Note: Please make sure to use the obtained information securely and in accordance with Firebase and FCM documentation, terms of service, and any applicable laws and regulations.' => 'Примечание. Обязательно используйте полученную информацию безопасно и в соответствии с условиями обслуживания документации Firebase и FCM, а также всеми применимыми законами и правилами.',
  'Write_a_message_in_the_Notification_Body' => 'Напишите сообщение в теле уведомления',
  'you_can_add_your_message_using_placeholders_to_include_dynamic_content._Here_are_some_examples_of_placeholders_you_can_use:' => 'Вы можете добавить свое сообщение, используя заполнители для включения динамического контента. Вот несколько примеров заполнителей, которые вы можете использовать:',
