  'smtp_mail_setup' => 'Настройка SMTP-почты',
  'Send Test Mail' => 'Отправить тестовое письмо',
  'Turn OFF' => 'Выключить',
  'Enabling mail configuration services will allow the system to send emails. Please ensure that you have correctly configured the SMTP settings to avoid potential issues with email delivery.' => 'Включение служб настройки почты позволит системе отправлять электронные письма. Убедитесь, что вы правильно настроили параметры SMTP, чтобы избежать потенциальных проблем с доставкой электронной почты.',
  'Disabling mail configuration services will prevent the system from sending emails. Please only turn off this service if you intend to temporarily suspend email sending. Note that this may affect system functionality that relies on email communication.' => 'Отключение служб настройки почты не позволит системе отправлять электронные письма. Пожалуйста, отключите эту услугу только в том случае, если вы намерены временно приостановить отправку электронной почты. Обратите внимание, что это может повлиять на функциональность системы, основанную на общении по электронной почте.',
  '*By Turning OFF mail configuration, all your mailing services will be off.' => '*При отключении конфигурации почты все ваши почтовые службы будут отключены.',
  'mailer_name' => 'Имя почтовой программы',
  'host' => 'Хост',
  'Ex_:_mail.6am.one' => 'Пример: mail.6am.one',
  'driver' => 'Водитель',
  'Ex : smtp' => 'Пример: смтп',
  'port' => 'Порт',
  'Ex : 587' => 'Пример: 587',
  'username' => 'Имя пользователя',
  'email_id' => 'Идентификатор электронной почты',
  'encryption' => 'Шифрование',
  'Ex : 5+ Characters' => 'Пример: 5+ персонажей',
  'Congratulations! Your SMTP mail has been setup successfully!' => 'Поздравляем! Ваша SMTP-почта успешно настроена!',
  'Go to test mail to check that its work perfectly or not!' => 'Зайдите в тестовую почту, чтобы проверить, работает она идеально или нет!',
  'Send a Test Mail to Your Email ? ' => 'Отправить тестовое письмо на свой адрес электронной почты?',
  'A test mail will be send to your email to confirm it works perfectly.' => 'На ваш адрес электронной почты будет отправлено тестовое письмо, чтобы подтвердить, что оно работает идеально.',
  'Find SMTP Server Details' => 'Найдите сведения о SMTP-сервере',
  'Contact your email service provider or IT administrator to obtain the SMTP server details, such as hostname, port, username, and password.' => 'Свяжитесь с поставщиком услуг электронной почты или ИТ-администратором, чтобы получить сведения о SMTP-сервере, такие как имя хоста, порт, имя пользователя и пароль.',
  'Note: If you\'re not sure where to find these details, check the email provider\'s documentation or support resources for guidance.' => 'Примечание. Если вы не уверены, где найти эти сведения, обратитесь к документации провайдера электронной почты или ресурсам поддержки.',
  'Configure SMTP Settings' => 'Настройте параметры SMTP',
  'Go to the SMTP mail setup page in the admin panel.' => 'Перейдите на страницу настройки SMTP-почты в админ-панели.',
  'Enter the obtained SMTP server details, including the hostname, port, username, and password.' => 'Введите полученные данные SMTP-сервера, включая имя хоста, порт, имя пользователя и пароль.',
  'Choose the appropriate encryption method (e.g., SSL, TLS) if required. Save the settings.' => 'При необходимости выберите подходящий метод шифрования (например, SSL TLS). Сохраните настройки.',
  'Test SMTP Connection' => 'Проверка SMTP-соединения',
  'Click on the "Send Test Mail" button to verify the SMTP connection.' => 'Нажмите кнопку «Отправить тестовое письмо», чтобы проверить SMTP-соединение.',
  'If successful, you will see a confirmation message indicating that the connection is working fine.' => 'В случае успеха вы увидите подтверждающее сообщение, указывающее, что соединение работает нормально.',
  'If not, double-check your SMTP settings and try again.' => 'Если нет, еще раз проверьте настройки SMTP и повторите попытку.',
  'Note: If you\'re unsure about the SMTP settings, contact your email service provider or IT administrator for assistance.' => 'Примечание. Если вы не уверены в настройках SMTP, обратитесь за помощью к своему поставщику услуг электронной почты или ИТ-администратору.',
  'Enable Mail Configuration' => 'Включить настройку почты',
  'If the SMTP connection test is successful, you can now enable the mail configuration services by toggling the switch to "ON."' => 'Если проверка SMTP-соединения прошла успешно, теперь вы можете включить службы настройки почты, переключив переключатель в положение ВКЛ.',
  'This will allow the system to send emails using the configured SMTP settings.' => 'Это позволит системе отправлять электронные письма, используя настроенные параметры SMTP.',
