  'This report will show all the orders in which the store discount has been used. The store discounts are: Free delivery, Coupon discount & item discounts(partial according to order commission).' => 'В этом отчете будут показаны все заказы, в которых была использована скидка магазина. Скидки магазина: Скидка по купону на бесплатную доставку и скидки на товары (частичные в зависимости от комиссии заказа).',
