  'search_by_disbursement_id' => 'Поиск по идентификатору выплаты',
  'Disbursement_List' => 'Список выплат',
  'If you disable this, the Deliveryman will deliver the order and update the status. He doesn’t need to verify the order with any code.' => 'Если вы отключите эту опцию, курьер доставит заказ и обновит статус. Ему не нужно подтверждать заказ каким-либо кодом.',
  'If you enable this, customers can place an order by simply uploading their prescriptions in the Pharmacy module from the Customer App or Website. Stores can enable/disable this feature from store settings if needed.' => 'Если вы включите эту опцию, клиенты смогут разместить заказ, просто загрузив свои рецепты в модуль «Аптеки» из приложения или веб-сайта для клиентов. При необходимости магазины могут включить/отключить эту функцию в настройках магазина.',
  'If disabled, this feature will be hidden from the Customer App, Website, and Store App & Panel.' => 'Если эта функция отключена, она будет скрыта на веб-сайте клиентского приложения, а также в приложении и панели магазина.',
  'If you enable this, customers can use the Home Delivery Option during checkout from the Customer App or Website.' => 'Если вы включите эту опцию, клиенты смогут использовать опцию доставки на дом во время оформления заказа из приложения или веб-сайта для клиентов.',
  'If you disable this, the Home Delivery feature will be hidden from the customer app and website.' => 'Если вы отключите эту функцию, функция доставки на дом будет скрыта в приложении и на веб-сайте клиента.',
  'If you enable this, customers can use the Takeaway feature during checkout from the Customer App or Website.' => 'Если вы включите эту функцию, клиенты смогут использовать функцию «Вынос» во время оформления заказа из приложения или веб-сайта для клиентов.',
  'If you disable this, the Takeaway feature will be hidden from the Customer App or Website.' => 'Если вы отключите эту функцию, функция «Еда на вынос» будет скрыта из приложения или веб-сайта клиента.',
  'If you enable this, customers can choose a suitable delivery schedule during checkout.' => 'Если вы включите эту опцию, клиенты смогут выбрать подходящий график доставки во время оформления заказа.',
  'If you disable this, the Scheduled Delivery feature will be hidden.' => 'Если вы отключите эту функцию, функция запланированной доставки будет скрыта.',
  'Order Cancellation Messages' => 'Сообщения об отмене заказа',
