  'By Turning OFF Offline Payment Option' => 'Отключив опцию автономной оплаты',
  'Customers will not be able to select Offline Payment as a payment method during checkout. Please review your settings and enable Offline Payment if you wish to offer this payment option to customers.' => 'Клиенты не смогут выбрать автономный платеж в качестве способа оплаты во время оформления заказа. Пожалуйста, проверьте свои настройки и включите автономную оплату, если вы хотите предложить этот вариант оплаты клиентам.',
  'Customers will be able to select Offline Payment as a payment method during checkout.' => 'Клиенты смогут выбрать автономный платеж в качестве способа оплаты во время оформления заказа.',
