  'panel_login_page_Url' => 'URL-адрес страницы входа в панель',
  'By enabling manual login, customers will get the option to create an account and log in using the necessary credentials & password in the app & website' => 'Включив вход вручную, клиенты получат возможность создать учетную запись и войти в систему, используя необходимые учетные данные и пароль в приложении и на веб-сайте.',
  'With OTP Login, customers can log in using their phone number. while new customers can create accounts instantly.' => 'С помощью OTP Login клиенты могут войти в систему, используя свой номер телефона. в то время как новые клиенты могут создавать учетные записи мгновенно.',
  'With Social Login, customers can log in using social media credentials. while new customers can create accounts instantly.' => 'Благодаря Social Login клиенты могут входить в систему, используя учетные данные социальных сетей. в то время как новые клиенты могут создавать учетные записи мгновенно.',
  'Enabling Google Login, customers can log in to the site using their existing Gmail credentials.' => 'Включив вход в Google, клиенты смогут войти на сайт, используя свои существующие учетные данные Gmail.',
  'Enabling Facebook Login, customers can log in to the site using their existing Facebook credentials' => 'Включив вход через Facebook, клиенты могут войти на сайт, используя свои существующие учетные данные Facebook.',
  'Enabling Apple Login, customers can log in to the site using their existing Apple login credentials, Only for Apple devices' => 'Включив Apple Login, клиенты могут войти на сайт, используя свои существующие учетные данные Apple. Только для устройств Apple.',
  'Verification' => 'Проверка',
  'The option you select from below will need to verify by customer from customer app/website.' => 'Вариант, выбранный вами ниже, должен будет быть подтвержден клиентом в приложении или на веб-сайте клиента.',
  'If Email verification is on, Customers must verify their email address with an OTP to complete the signup process.' => 'Если проверка электронной почты включена, клиенты должны подтвердить свой адрес электронной почты с помощью OTP, чтобы завершить процесс регистрации.',
  'If Phone Number verification is on, Customers must verify their Phone Number with an OTP to complete the signup process.' => 'Если проверка номера телефона включена, клиенты должны подтвердить свой номер телефона с помощью OTP, чтобы завершить процесс регистрации.',
  'Important Alert !' => 'Важное предупреждение!',
  'At least one login method must remain active for the customer; otherwise, they will be unable to log in to the system' => 'Для клиента должен оставаться активным хотя бы один метод входа в систему, иначе он не сможет войти в систему.',
  'Set Up SMS Configuration First' => 'Сначала настройте конфигурацию SMS',
  'It looks like your SMS configuration is not set up yet. To enable the OTP system, please set up the SMS configuration first.' => 'Похоже, ваша конфигурация SMS еще не настроена. Чтобы включить систему OTP, сначала настройте конфигурацию SMS.',
  'Go to SMS Configuration' => 'Зайдите в конфигурацию СМС',
  'If you are activating only social login as the login method, you must enable at least one option between Google and Facebook for Android users.' => 'Если вы активируете в качестве метода входа только вход через социальную сеть, вам необходимо включить хотя бы один вариант между Google и Facebook для пользователей Android.',
  'If you are activating social login as the login method, you must enable at least one option between Google, Facebook & Apple.' => 'Если вы активируете вход через социальную сеть в качестве метода входа, вам необходимо включить хотя бы один вариант между Google, Facebook и Apple.',
  'Set Up Google Configuration First' => 'Сначала настройте конфигурацию Google',
  'It looks like your Google Login configuration is not set up yet. To enable the Google Login option, please set up the Google configuration first.' => 'Похоже, ваша конфигурация входа в Google еще не настроена. Чтобы включить опцию входа в Google, сначала настройте конфигурацию Google.',
  'Go to Google Configuration' => 'Зайдите в конфигурацию Google',
  'Set Up Facebook Configuration First' => 'Сначала настройте конфигурацию Facebook',
  'It looks like your Facebook Login configuration is not set up yet. To enable the Facebook Login option, please set up the Facebook configuration first.' => 'Похоже, ваша конфигурация входа в Facebook еще не настроена. Чтобы включить опцию входа через Facebook, сначала настройте конфигурацию Facebook.',
  'Go to Facebook Configuration' => 'Зайдите в конфигурацию Facebook',
  'Set Up Apple Configuration First' => 'Сначала настройте конфигурацию Apple',
  'It looks like your Apple Login configuration is not set up yet. To enable the Apple Login option, please set up the Apple configuration first.' => 'Похоже, ваша конфигурация входа в Apple еще не настроена. Чтобы включить функцию входа через Apple, сначала настройте конфигурацию Apple.',
  'Go to Apple Configuration' => 'Зайдите в конфигурацию Apple',
  'It looks like your SMS configuration is not set up yet. To enable the phone verification, please set up the SMS configuration first.' => 'Похоже, ваша конфигурация SMS еще не настроена. Чтобы включить проверку телефона, сначала настройте конфигурацию SMS.',
  'Set Up Email Configuration First' => 'Сначала настройте конфигурацию электронной почты',
  'It looks like your Email configuration is not set up yet. To enable the email verification, please set up the SMS configuration first.' => 'Похоже, ваша конфигурация электронной почты еще не настроена. Чтобы включить проверку электронной почты, сначала настройте конфигурацию SMS.',
  'Go to Mail Configuration' => 'Зайдите в конфигурацию почты',
  'login_settings_data_updated_successfully' => 'Данные настроек входа успешно обновлены',
