  'Want to disable Firebase OTP Verification?' => 'Хотите отключить проверку OTP Firebase?',
  'With Firebase OTP enabled, verification codes will be sent through Firebase.' => 'Если Firebase OTP включен, коды подтверждения будут отправляться через Firebase.',
  'Enable Firebase OTP means users will not receive verification codes through Email or SMS Although those methods are activated.' => 'Включение Firebase OTP означает, что пользователи не будут получать коды подтверждения по электронной почте или SMS, хотя эти методы активированы.',
  'If you disable Firebase OTP, users will no longer receive verification codes via Firebase. You must activate Email or SMS verification as an alternative' => 'Если вы отключите Firebase OTP, пользователи больше не будут получать коды подтверждения через Firebase. В качестве альтернативы вы должны активировать проверку по электронной почте или SMS.',
