  'This is the rate that will be applied to all taxable items or services.' => 'Это ставка, которая будет применяться ко всем налогооблагаемым статьям или услугам.',
  'Save the Tax' => 'Экономьте налоги',
  'Click Submit to add the new tax.' => 'Нажмите «Отправить», чтобы добавить новый налог.',
  'Click Reset if you need to clear the form before saving.' => 'Нажмите «Сбросить», если вам нужно очистить форму перед сохранением.',
  'You can create multiple taxes for different purposes — for example, separate ones for product, service, and delivery.' => 'Вы можете создать несколько налогов для разных целей — например, отдельные для продукта, услуги и доставки.',
  'Follow these steps to add a new tax rate:' => 'Выполните следующие действия, чтобы добавить новую налоговую ставку:',
  'Edit or Manage Existing Taxes' => 'Редактировать или управлять существующими налогами',
  'Once a tax is created, you cannot change its name or delete it (for data integrity).' => 'После создания налога вы не сможете изменить его название или удалить (для целостности данных).',
  'However, you can update the tax rate anytime if your government updates the tax percentage.' => 'Однако вы можете обновить ставку налога в любое время, если ваше правительство обновит процент налога.',
  'Manage all your created taxes easily from the Tax List page.' => 'Легко управляйте всеми созданными вами налогами со страницы списка налогов.',
  'Use the Export button to download a copy for backup or accounting records.' => 'Используйте кнопку «Экспорт», чтобы загрузить копию для резервного копирования или учета.',
  'Toggle the Status on or off to quickly enable or disable a tax.' => 'Включите или выключите статус, чтобы быстро включить или отключить налог.',
  'You can decide:' => 'Вы можете решить:',
  'Whether tax should be included in the product price or added separately' => 'Должен ли налог быть включен в цену продукта или добавлен отдельно',
  'Which parts of the order should have taxes applied — items, delivery fees, or packaging' => 'К каким частям заказа следует применять налоги: товары, стоимость доставки или упаковка.',
  'This gives you full control over how your business handles tax visibility and accuracy.' => 'Это дает вам полный контроль над тем, как ваш бизнес обеспечивает прозрачность и точность налогов.',
  'Tax Calculation Method' => 'Метод расчета налога',
  'You can choose one of two ways to calculate tax:' => 'Вы можете выбрать один из двух способов расчета налога:',
  'Calculate Tax Included in Product Price' => 'Рассчитать налог, включенный в цену продукта',
  'The tax is already included in the listed item price.' => 'Налог уже включен в указанную цену товара.',
  'The customer sees a single total price (no separate tax line).' => 'Клиент видит единую общую цену (без отдельной налоговой строки).',
  'Invoices and reports won’t show separate VAT amounts.' => 'В счетах и отчетах не будут отображаться отдельные суммы НДС.',
  'Use this method if your displayed prices are “tax-included.' => 'Используйте этот метод, если отображаемые цены «с учетом налогов».',
  'Calculate Tax Excluded from Product Price' => 'Рассчитать налог, не включенный в цену продукта',
  'The tax is added on top of the item price.' => 'Налог добавляется к цене товара.',
  'Customers will see a separate tax line during checkout and in their invoice.' => 'Клиенты увидят отдельную строку налога во время оформления заказа и в счете.',
  'This method gives you clear, transparent VAT reporting.' => 'Этот метод дает вам четкую и прозрачную отчетность по НДС.',
  'Recommendation: Use “Tax Excluded from Product Price” if you want to show taxes separately for better reporting.' => 'Рекомендация: используйте «Налог не включен в цену продукта», если вы хотите отображать налоги отдельно для улучшения отчетности.',
  'Tax Effect on Orders' => 'Налоговый эффект на заказы',
  'Before activation:' => 'До активации:',
  'Orders placed earlier will not have any tax added.' => 'К заказам, размещенным ранее, налог не добавляется.',
  'After activation:' => 'После активации:',
  'All new orders will automatically calculate and apply the correct tax.' => 'Для всех новых заказов автоматически рассчитывается и применяется правильный налог.',
  'After deactivation:' => 'После деактивации:',
  'If you turn off tax again, future orders will not include tax until reactivated.' => 'Если вы снова отключите налог, будущие заказы не будут включать налог до тех пор, пока вы не активируете его снова.',
  'This ensures older orders stay accurate while new ones follow updated rules.' => 'Это гарантирует, что старые заказы остаются точными, а новые следуют обновленным правилам.',
  'Flexible Tax Application Options' => 'Гибкие возможности подачи налоговых деклараций',
  'Order-wise Tax:' => 'Налог по заказу:',
  'One flat tax rate applies to the total order.' => 'Ко всей сумме заказа применяется одна фиксированная ставка налога.',
  'Product-wise Tax: ' => 'Налог на продукт: ',
  'Each product or food item can have its own tax rate.' => 'Каждый продукт или продукт питания может иметь свою собственную ставку налога.',
  'Category-wise Tax: ' => 'Налог по категориям: ',
  'Different product categories can carry different tax rates.' => 'Различные категории продуктов могут иметь разные налоговые ставки.',
  'This flexibility lets you match complex tax rules for restaurants, grocery stores, or other service types.' => 'Такая гибкость позволяет вам соответствовать сложным налоговым правилам для ресторанов, продуктовых магазинов или других типов услуг.',
  'Uploaded Prescription Orders (Pharmacy Module Only)' => 'Загруженные заказы на рецепты (только модуль «Аптеки»)',
  'For pharmacy modules, tax applies order-wise on uploaded prescription orders.' => 'Для аптечных модулей налог взимается в зависимости от загруженных заказов на рецепты.',
  'You can set the tax type and rate specifically for these orders.' => 'Вы можете установить тип и ставку налога специально для этих заказов.',
  'You can also configure tax for packaging charges.' => 'Вы также можете настроить налог на оплату упаковки.',
  'If enabled, packaging costs will include tax as per your setup — ensuring your total billing remains compliant.' => 'Если эта функция включена, стоимость упаковки будет включать налог в соответствии с вашими настройками, что гарантирует соответствие общей суммы счетов.',
  'Example: If packaging costs $2 and tax is 10%, the total will show as $2.20.' => 'Пример. Если стоимость упаковки составляет 2 доллара США, а налог составляет 10 %, общая сумма будет равна 2,20 доллара США.',
  'Final Step – Save Your Setup' => 'Последний шаг — сохраните настройки',
  'After completing all configurations:' => 'После завершения всех настроек:',
  'Click Save Information to apply changes.' => 'Нажмите «Сохранить информацию», чтобы применить изменения.',
  'Click Reset if you want to start over or discard unsaved edits.' => 'Нажмите «Сбросить», если вы хотите начать заново или отменить несохраненные изменения.',
  'Once saved, your tax setup will instantly affect all applicable orders moving forward.' => 'После сохранения ваша настройка налога мгновенно повлияет на все применимые заказы в дальнейшем.',
