  'If you want to set up your own landing page please follow tha instructions below' => 'Если вы хотите настроить собственную целевую страницу, следуйте инструкциям ниже.',
  'You can add your customized landing page via URL or upload ZIP file of the landing page.' => 'Вы можете добавить свою персонализированную целевую страницу через URL-адрес или загрузить ZIP-файл целевой страницы.',
  'If you want to use URL option. Just host you landing page and copy the page URL and click save information.' => 'Если вы хотите использовать опцию URL. Просто разместите целевую страницу, скопируйте URL-адрес страницы и нажмите «Сохранить информацию».',
  'If you want to upload your landing page source code file:' => 'Если вы хотите загрузить файл исходного кода целевой страницы:',
  'Create an html file named index.blade.php and insert your landing page design code and make a zip file.' => 'Создайте html-файл с именем index.blade.php, вставьте код дизайна целевой страницы и создайте zip-файл.',
  'Upload the zip file in file upload section and click save information.' => 'Загрузите zip-файл в раздел загрузки файлов и нажмите «Сохранить информацию».',
  'Upload PHP File' => 'Загрузить PHP-файл',
  'Here you need to upload your custome designed PHP file that will work as a Admin Landing Page.' => 'Здесь вам необходимо загрузить специально разработанный PHP-файл, который будет работать как целевая страница администратора.',
  'Upload file must be zip file format in and click save information.' => 'Загрузите файл в формате zip и нажмите «Сохранить информацию».',
