  'Content This Title appears in browser tabs, search results, and link previews. Use a short ,clear, and keyword-focused title(recommended: 80-100 characters)' => 'Содержание Этот заголовок отображается на вкладках браузера, в результатах поиска и при предварительном просмотре ссылок. Используйте короткий, понятный заголовок, ориентированный на ключевые слова (рекомендуется: 80–100 символов).',
  'A brief summary that appears under your page title in search results. Keep it compelling and relevant (recommended: 120-160 characters)' => 'Краткое описание, которое отображается под заголовком вашей страницы в результатах поиска. Сделайте его привлекательным и актуальным (рекомендуется: 120–160 символов).',
  'Allow search engines to put this web page on their list or index & show it on search results' => 'Разрешить поисковым системам включать эту веб-страницу в свой список или индекс и показывать ее в результатах поиска.',
  'Disallow search engines from putting this web page on their list or index, and do not show it on search results' => 'Запретить поисковым системам включать эту веб-страницу в свой список или индекс и не показывать ее в результатах поиска.',
  'Instruct search engines not to follow links from this webpage.' => 'Попросите поисковые системы не переходить по ссылкам с этой веб-страницы.',
  ' Prevent images from being listed or indexed by search engines' => ' Запретить отображение или индексацию изображений поисковыми системами.',
  'Instruct search engines not to show a summary or snippet of this webpage s content in search results.' => 'Попросите поисковые системы не показывать краткое содержание или фрагмент содержания этой веб-страницы в результатах поиска.',
  'Determine the maximum length of a snippet or preview text of the webpage.' => 'Определите максимальную длину фрагмента или текста предварительного просмотра веб-страницы.',
  'Determine the maximum duration of a video preview that search engines will display' => 'Определите максимальную продолжительность предварительного просмотра видео, которое будут отображать поисковые системы.',
  'Determine the maximum size or dimensions of an image preview that search engines will display' => 'Определите максимальный размер или размеры предварительного просмотра изображения, которое будут отображать поисковые системы.',
  'Define the time period during which customers have to return a parcel' => 'Определите период времени, в течение которого клиенты должны вернуть посылку.',
