  'index.blade.php' => 'Индекс.blade.php',
  'Currently You are Not Using' => 'В настоящее время вы не используете',
  'Zip file is required, upload zip file first' => 'Требуется ZIP-файл. Сначала загрузите ZIP-файл.',
  'This feature allows the admin to configure how and when earnings are disbursed to restaurants and delivery personnel. Proper setup ensures timely payouts, automated processing, and compliance with operational rules.' => 'Эта функция позволяет администратору настраивать, как и когда доходы выплачиваются ресторанам и персоналу службы доставки. Правильная настройка обеспечивает своевременные выплаты, автоматизацию обработки и соблюдение правил работы.',
  'Disbursement Request Setup' => 'Настройка запроса на выплату',
  'The System PHP Path specifies the location of the PHP executable file that will be used to run automated disbursement scripts. Setting the correct PHP path ensures that the system can execute scheduled or automated disbursement processes without errors.' => 'Системный путь PHP указывает расположение исполняемого файла PHP, который будет использоваться для запуска сценариев автоматической выплаты. Установка правильного пути PHP гарантирует, что система сможет без ошибок выполнять запланированные или автоматические процессы выплат.',
  'The system automatically processes payouts according to predefined schedules (daily, weekly, or monthly).' => 'Система автоматически обрабатывает выплаты по заранее заданному графику (ежедневно, еженедельно или ежемесячно).',
  'Automated Disbursement' => 'Автоматизированная выплата',
  'Cron Command for Disbursement' => 'Команда Cron для выплаты средств',
  'Admin reviews and approves each payout request before processing.' => 'Администратор проверяет и утверждает каждый запрос на выплату перед обработкой.',
  'Manual Disbursement' => 'Выплата вручную',
  'The system supports two types of disbursement requests for restaurants and delivery personnel: Manual and Automated. These settings determine how earnings are transferred from the platform to the recipients.' => 'Система поддерживает два типа запросов на выплаты для ресторанов и персонала службы доставки: ручной и автоматический. Эти настройки определяют, как доходы передаются с платформы получателям.',
  'The Disbursement Setup feature allows the admin to manage the payout of earnings to restaurants and delivery personnel. It ensures timely and accurate settlements based on completed orders, commissions, and deductions.' => 'Функция настройки выплат позволяет администратору управлять выплатой доходов ресторанам и персоналу службы доставки. Это обеспечивает своевременные и точные расчеты на основе выполненных заказов, комиссий и отчислений.',
  'Disbursement Guideline' => 'Руководство по выплате средств',
  'This feature allows the admin to configure how and when earnings are disbursed to vendors and delivery personnel. Proper setup ensures timely payouts, automated processing, and compliance with operational rules.' => 'Эта функция позволяет администратору настраивать, как и когда доходы выплачиваются поставщикам и персоналу доставки. Правильная настройка обеспечивает своевременные выплаты, автоматизацию обработки и соблюдение правил работы.',
  'The system supports two types of disbursement requests for vendors and delivery personnel: Manual and Automated. These settings determine how earnings are transferred from the platform to the recipients.' => 'Система поддерживает два типа запросов на выплаты для поставщиков и персонала доставки: вручную и автоматически. Эти настройки определяют, как доходы передаются с платформы получателям.',
  'The Disbursement Setup feature allows the admin to manage the payout of earnings to vendors and delivery personnel. It ensures timely and accurate settlements based on completed orders, commissions, and deductions.' => 'Функция настройки выплат позволяет администратору управлять выплатой доходов поставщикам и персоналу доставки. Это обеспечивает своевременные и точные расчеты на основе выполненных заказов, комиссий и отчислений.',
