  '_otherwise,_all_users_will_be_unable_to_pay_via_digital_payments.' => ' в противном случае все пользователи не смогут платить с помощью цифровых платежей.',
  'The supported country field is required when status is 1.' => 'Поле поддерживаемой страны является обязательным, если статус равен 1.',
  '_thus_users_cannot_view_digital_payment_options_in_their_websites_and_apps_._You_must_activate_at_least_one_digital_payment_method_that_supports_' => ' таким образом, пользователи не могут просматривать варианты цифровых платежей на своих веб-сайтах и в приложениях. Вы должны активировать хотя бы один способ цифровой оплаты, который поддерживает ',
  'The access token field is required when status is 1.' => 'Поле токена доступа является обязательным, если статус равен 1.',
  'Currently,_there_is_no_digital_payment_method_is_set_up_that_supports_' => 'В настоящее время не существует способа цифровой оплаты, поддерживающего ',
  'payment_method_status_updated' => 'Статус способа оплаты обновлен.',
  'Search by payment method name' => 'Поиск по названию способа оплаты',
  'When select Test option: during use this from website/app use fake required data to test payment gateway work properly or not.' => 'При выборе опции «Тест»: во время использования этого с веб-сайта/приложения используйте поддельные необходимые данные, чтобы проверить правильность работы платежного шлюза.',
  'When select live option: during use this from website/app need real required data. other wise this gateway can\'t work.' => 'При выборе опции «Живой»: во время использования этого веб-сайта/приложения требуются реальные необходимые данные. в противном случае этот шлюз не сможет работать.',
  'Digital Payment Methods List' => 'Список цифровых способов оплаты',
  'Currently this module is available' => 'В настоящее время этот модуль доступен',
  'make_default' => 'Сделать по умолчанию',
  'This zone is set as the default for customers who visit the app or website without choosing a location.' => 'Эта зона устанавливается по умолчанию для клиентов, которые посещают приложение или веб-сайт, не выбирая местоположение.',
  'default_zone' => 'Зона по умолчанию',
  'Default_Status' => 'Статус по умолчанию',
  'If_you_set_this_zone as default for customers who visit the app or website without choosing a location.' => 'Если вы установите эту зону по умолчанию для клиентов, которые посещают приложение или веб-сайт, не выбирая местоположение.',
  'Want_to_make_this_as_default_zone?' => 'Хотите сделать это зоной по умолчанию?',
  'When enabled, customers who visit the app or website without choosing a location will be assigned to this zone.' => 'Если эта функция включена, клиенты, которые посещают приложение или веб-сайт без выбора местоположения, будут отнесены к этой зоне.',
  'zone_default_status_updated' => 'Статус зоны по умолчанию обновлен.',
  'Please select at least one module for extra packaging charge' => 'Пожалуйста, выберите хотя бы один модуль для дополнительной оплаты за упаковку.',
  'At least one delivery method Home Delivery or Takeaway must be selected for your business' => 'Для вашей компании должен быть выбран хотя бы один способ доставки: «Доставка на дом» или «На вынос».',
  'Note : Don’t forget to save the information before leaving this page ' => 'Примечание. Не забудьте сохранить информацию, прежде чем покинуть эту страницу. ',
  'To receive order notifications properly, select the notification type based on your preference:' => 'Чтобы правильно получать уведомления о заказах, выберите тип уведомления в зависимости от ваших предпочтений:',
  'Manual Notification: You need to send order notifications manually for each order update.' => 'Уведомление вручную: вам необходимо отправлять уведомления о заказах вручную для каждого обновления заказа.',
  'Firebase Notification: Order notifications will be sent automatically. Ensure' => 'Уведомление Firebase: уведомления о заказах будут отправляться автоматически. Обеспечить',
  'is completed and notification messages are set up in the Notification Message section.' => 'Завершено, и в разделе «Сообщение уведомления» настроены уведомления.',
  'Free Delivery Setup' => 'Настройка бесплатной доставки',
  'Are you sure to enable Free Delivery?' => 'Вы уверены, что включили бесплатную доставку?',
  'Are you sure to disable Free Delivery?' => 'Вы уверены, что отключите бесплатную доставку?',
  'After enable customers will not be charged a delivery fee for eligible orders.' => 'После включения с клиентов не будет взиматься плата за доставку соответствующих критериям заказов.',
  'After disable delivery charges will apply to all new orders based on your delivery settings.' => 'После отключения стоимость доставки будет применяться ко всем новым заказам в зависимости от ваших настроек доставки.',
  'Vendors will no longer have the option to cancel. They will need to contact the admin to request any order cancellations.' => 'У продавцов больше не будет возможности отменить подписку. Им нужно будет связаться с администратором, чтобы запросить отмену заказа.',
  'Vendors will be able to cancel orders directly from their panel if they cannot fulfill them.' => 'Продавцы смогут отменять заказы прямо со своей панели, если не смогут их выполнить.',
  'Are you sure to not allow vendor to cancel orders?' => 'Вы уверены, что не разрешите поставщику отменять заказы?',
  'After disable the self-registration link will be hidden. You will need to manually add every new vendor from the admin panel.' => 'После отключения ссылка на саморегистрацию будет скрыта. Вам нужно будет вручную добавлять каждого нового поставщика из панели администратора.',
  'If disabled, vendors will not be able to duplicate products or create new products using the gallery.' => 'Если этот параметр отключен, продавцы не смогут дублировать продукты или создавать новые продукты с помощью галереи.',
  'If you disable this, vendors can not access all products of other available vendors.' => 'Если вы отключите это, поставщики не смогут получить доступ ко всем продуктам других доступных поставщиков.',
  'If you enable this, vendors can access all products of other available vendors' => 'Если вы включите это, поставщики смогут получить доступ ко всем продуктам других доступных поставщиков.',
  'If disabled, vendors can not reply to reviews left for their orders.' => 'Если отключено, продавцы не смогут отвечать на отзывы, оставленные к их заказам.',
  'Are you sure to disable Vendor Can Reply Review?' => 'Вы уверены, что отключили проверку возможности ответа поставщика?',
  'Are you sure to enable Vendor Can Reply Review?' => 'Вы уверены, что включили проверку возможности ответа поставщика?',
  'Are you sure to disable Access All Products?' => 'Вы уверены, что отключили доступ ко всем продуктам?',
  'Are you sure to enable Access All Products?' => 'Вы уверены, что включили доступ ко всем продуктам?',
  'This allows vendors to duplicate products and create new products using the gallery.' => 'Это позволяет продавцам дублировать продукты и создавать новые продукты с помощью галереи.',
  'Are you sure to disable Product Gallery?' => 'Вы уверены, что отключите галерею товаров?',
  'Are you sure to enable Product Gallery?' => 'Вы уверены, что включили Галерею товаров?',
  'This allows new business owners to sign up and apply to sell on your platform by themselves.' => 'Это позволяет новым владельцам бизнеса самостоятельно зарегистрироваться и подать заявку на продажу на вашей платформе.',
  'Are you sure to disable vendor Self Registration?' => 'Вы уверены, что отключите саморегистрацию поставщика?',
  'Are you sure to enable vendor Self Registration?' => 'Вы уверены, что включили саморегистрацию поставщика?',
  'Are you sure to allow vendor to cancel orders?' => 'Вы уверены, что разрешите поставщику отменять заказы?',
  'Please select at least one option for Update Existing Product' => 'Пожалуйста, выберите хотя бы один вариант для обновления существующего продукта.',
  'Available Option for Update Existing Product' => 'Доступный вариант обновления существующего продукта',
  'After disable Vendors will not be suspended even if their cash in hand exceeds the set limit.' => 'После отключения Продавцы не будут заблокированы, даже если их наличные на кассе превысят установленный лимит.',
  'After enable vendor will be automatically suspended when their cash in hand exceeds the allowed limit.' => 'После включения поставщик будет автоматически заблокирован, если его наличные на кассе превысят разрешенный лимит.',
  'Are you sure to disable Cash in Hand Overflow Suspension?' => 'Вы уверены, что отключили приостановку переполнения наличных в руках?',
  'Are you sure to enable Cash in Hand Overflow Suspension?' => 'Вы уверены, что включили приостановку переполнения наличных в выдаче?',
  'This field is disabled as Cash-in-Hand Overflow suspension is turned OFF' => 'Это поле неактивно, поскольку приостановка переполнения наличных в кассе отключена.',
  'This can not be undone.' => 'Это невозможно отменить.',
  'enter_number' => 'Введите номер',
  'Ex:_reference,_Name' => 'Пример: ссылка, имя.',
  'Configure limits for cash collected by vendors and suspension rules for exceeding limits.' => 'Настройте лимиты на наличные, взимаемые продавцами, и правила приостановки за превышение лимитов.',
  'Control vendor-related settings such as: Vendor registration availability, Order cancellation permission, Replying to customer reviews, Access to the product gallery, Access to all products. These settings are managed at the vendor level.' => 'Управляйте настройками, связанными с поставщиком, такими как: доступность регистрации поставщика, разрешение на отмену заказа, ответы на отзывы клиентов, доступ к галерее продуктов, доступ ко всем продуктам. Эти параметры управляются на уровне поставщика.',
  'Cash-in-hand control allows the platform to monitor and limit the amount of cash collected by vendors from Cash on Delivery (COD) orders. This feature helps reduce financial risk and ensures timely settlement between the vendor and the platform.' => 'Контроль наличности позволяет платформе отслеживать и ограничивать сумму денежных средств, полученных поставщиками от заказов наложенным платежом (COD). Эта функция помогает снизить финансовый риск и обеспечивает своевременный расчет между поставщиком и платформой.',
  'This section manages which changes to products by vendors require admin approval before they are applied.' => 'В этом разделе указывается, какие изменения в продуктах поставщиков требуют одобрения администратора перед их применением.',
  'Product Approval' => 'Одобрение продукта',
  'These settings are managed at the vendor level.' => 'Эти параметры управляются на уровне поставщика.',
  'Access to all products' => 'Доступ ко всем продуктам',
  'These reasons will be shown to users when they try to cancel an order.' => 'Эти причины будут показаны пользователям, когда они попытаются отменить заказ.',
  'business_info' => 'Информация о компании',
  'Mark a default cancellation reason' => 'Отметьте причину отмены по умолчанию',
  'Setup your business payment options from here' => 'Настройте способы оплаты для вашего бизнеса здесь',
  'Access to the product gallery' => 'Доступ к галерее товаров',
  'Set a reason as active or inactive' => 'Установите причину как активную или неактивную',
  'Deleting this payment method will permanently remove its data.' => 'Удаление этого способа оплаты приведет к безвозвратному удалению его данных.',
  'Do you want to delete this payment method?' => 'Вы хотите удалить этот способ оплаты?',
  'At_least_one_payment_option_must_be_selected' => 'Должен быть выбран хотя бы один вариант оплаты',
  'At least one payment option must be selected' => 'Должен быть выбран хотя бы один вариант оплаты',
  'Referrer' => 'реферер',
  'Disabling this feature will require customers to pay the full amount at checkout.' => 'Отключение этой функции потребует от клиентов оплатить полную сумму при оформлении заказа.',
  'Enabling partial payment will allow customers to pay partially.' => 'Включение частичной оплаты позволит клиентам платить частично.',
  'Combined Payment?' => 'Комбинированная оплата?',
  'Are you sure turn off' => 'Ты уверен, что выключишь?',
  'Are you sure turn on' => 'Ты уверен, что включишь?',
  'At least one partial payment option must be selected' => 'Необходимо выбрать хотя бы один вариант частичной оплаты.',
  'This feature enables customers to partially pay with their wallet balance and complete the payment using other available payment methods.' => 'Эта функция позволяет клиентам частично оплатить баланс своего кошелька и завершить оплату, используя другие доступные способы оплаты.',
  'Allow Combined Payment' => 'Разрешить комбинированный платеж',
  'combined_payment_method_is_required' => 'Требуется комбинированный способ оплаты.',
  'Payment Settings Guideline' => 'Руководство по настройке платежей',
  'Set the method(s) that customers can pay the remainder after partial payment.' => 'Установите метод(ы), с помощью которых клиенты смогут оплатить остаток после частичной оплаты.',
  'The Partial Payment feature allows customers to split an order payment into two parts. An initial amount is paid using the customer’s wallet balance, and the remaining amount can be paid using Cash on Delivery (COD) or Digital Payment. This feature provides greater payment flexibility and helps customers place orders even when their wallet balance is insufficient for the full amount.' => 'Функция частичной оплаты позволяет клиентам разделить оплату заказа на две части. Первоначальная сумма выплачивается с использованием баланса кошелька клиента, а оставшаяся сумма может быть оплачена с помощью наложенного платежа (COD) или цифрового платежа. Эта функция обеспечивает большую гибкость оплаты и помогает клиентам размещать заказы, даже если на балансе их кошелька недостаточно полной суммы.',
  'Combined Payment' => 'Комбинированный платеж',
  'Setup your business payment options from here.' => 'Настройте варианты оплаты для вашего бизнеса отсюда.',
  'Create and edit cancellation reasons' => 'Создание и редактирование причин отмены',
  'No Payment Method List' => 'Нет списка способов оплаты',
  'Payment Note' => 'Примечание к оплате',
  'Ex: Miler' => 'Пример: Милер',
  'Pay your bill using any of the payment method below' => 'Оплатите счет любым из способов оплаты, указанных ниже.',
  'and input the required information.' => 'И введите необходимую информацию.',
  'Input field Name' => 'Поле ввода Имя',
  'Ex: Account Number' => 'Пример: номер счета',
  'Input data' => 'Входные данные',
  'Ex: 1235 5648 2314' => 'Пример: 1235 5648 2314',
  'By disabling Ucash, customers will not be able to use it as a payment method.' => 'Отключив Ucash, клиенты не смогут использовать его в качестве способа оплаты.',
  'By enabling Ucash, customers can securely pay with their Ucash account.' => 'Включив Ucash, клиенты смогут безопасно расплачиваться со своей учетной записи Ucash.',
  'Turn OFF Ucash payment method' => 'Отключить способ оплаты Ucash',
  'Replying to customer reviews' => 'Отвечая на отзывы клиентов',
  'This section allows the admin to manage order cancellation reasons for different user types. You can:' => 'Этот раздел позволяет администратору управлять причинами отмены заказа для разных типов пользователей. Вы можете:',
  'Note : Don’t forget to save the information before leaving this page.' => 'Примечание. Не забудьте сохранить информацию, прежде чем покинуть эту страницу.',
  'This will make your app and website live. Customers will be able to browse your services and place orders again.' => 'Это оживит ваше приложение и веб-сайт. Клиенты снова смогут просматривать ваши услуги и размещать заказы.',
  'This will temporarily disable the selected systems at the scheduled date and time. You can turn it off anytime after maintenance is complete.' => 'Это временно отключит выбранные системы в запланированную дату и время. Вы можете отключить его в любое время после завершения технического обслуживания.',
  'Are you sure to disable Maintenance Mode?' => 'Вы уверены, что отключите режим обслуживания?',
  'Are you sure to enable Maintenance Mode?' => 'Вы уверены, что включили режим обслуживания?',
  'Turn off the Maintenance Mode will activate your selected systems.' => 'Отключение режима обслуживания активирует выбранные вами системы.',
  'Are you sure to turn off maintenance mode?' => 'Вы уверены, что выключили режим обслуживания?',
  'Are you sure to turn on maintenance mode?' => 'Вы уверены, что включите режим обслуживания?',
  'Country' => 'Страна',
  'Type your email' => 'Введите адрес электронной почты',
  'Business Name' => 'Название компании',
  'Set up Order Cancellation Messages' => 'Настройка сообщений об отмене заказа',
  'Applying delivery verification methods to ensure successful delivery, and selecting the order confirmation model to define how orders are approved and processed within the system.' => 'Применение методов проверки доставки для обеспечения успешной доставки и выбор модели подтверждения заказа, чтобы определить, как заказы утверждаются и обрабатываются в системе.',
  'Order cancellation permission' => 'Разрешение на отмену заказа',
  'Automated Message' => 'Автоматизированное сообщение',
  'Disbursement' => 'Выплата',
  'Priority Setup' => 'Приоритетная настройка',
  'Currency Setup page' => 'Страница настройки валюты',
  'To set your default currency, go to the' => 'Чтобы установить валюту по умолчанию, перейдите в раздел',
  'This option lets you select which modules require extra packaging fees.' => 'Эта опция позволяет вам выбрать, какие модули требуют дополнительной платы за упаковку.',
  'At least one business model must be selected' => 'Необходимо выбрать хотя бы одну бизнес-модель.',
  'Here you setup your business others setup' => 'Здесь вы настраиваете свой бизнес, другие настраивают',
  'Others Setup' => 'Другие настройки',
  'refund_policy_page' => 'Страница политики возврата',
  'Maintenance is on.' => 'Техническое обслуживание включено.',
  'This is a short message shown on the website to let visitors know that the site uses cookies to collect information and improve their browsing experience' => 'Это короткое сообщение, отображаемое на веб-сайте, чтобы сообщить посетителям, что сайт использует файлы cookie для сбора информации и улучшения их просмотра.',
  'This is a short statement that shows your company owns the content on your website. It usually includes the copyright symbol (©), the year, and your company name.' => 'Это короткое заявление, которое показывает, что контент на вашем сайте принадлежит вашей компании. Обычно он включает в себя символ авторского права (©), год и название вашей компании.',
  'Copyright text' => 'Авторский текст',
  'Vendor registration availability' => 'Наличие регистрации продавца',
  'Extra Packaging Charge' => 'Дополнительная плата за упаковку',
  'Content Setup' => 'Настройка контента',
  'This option allows users to pick their country code while typing a phone number.' => 'Эта опция позволяет пользователям выбирать код своей страны при вводе номера телефона.',
  'Country Picker' => 'Выбор страны',
  'Use this option to add extra fees to customer orders based on specific, predefined conditions. These charges are added automatically at checkout and are visible to both customers and vendors.' => 'Используйте эту опцию, чтобы добавить дополнительные сборы к заказам клиентов на основе конкретных, заранее определенных условий. Эти сборы добавляются автоматически при оформлении заказа и видны как покупателям, так и продавцам.',
  'In the Commission-based model, the platform earns revenue by taking a predefined fixed percentage from each completed order. The commission is automatically deducted from the order value before the remaining amount is settled with the vendor or service provider.' => 'В модели, основанной на комиссии, платформа получает доход, взимая заранее определенный фиксированный процент с каждого выполненного заказа. Комиссия автоматически вычитается из стоимости заказа до того, как оставшаяся сумма будет оплачена продавцу или поставщику услуг.',
  'Commission-based model' => 'Комиссионная модель',
  'popular_store_page' => 'Страница популярного магазина',
  'latest_store_page' => 'Последняя страница магазина',
  'privacy_policy_page' => 'Страница политики конфиденциальности',
  'page_meta_data_updated_successfully' => 'Метаданные страницы успешно обновлены.',
  'Search Page Name' => 'Имя страницы поиска',
  'Pages' => 'Страницы',
  'home_page' => 'Домашняя страница',
  'Edit Content' => 'Редактировать контент',
  'top_offers_page' => 'Страница лучших предложений',
  'brands_page' => 'Страница брендов',
  'search_page' => 'Страница поиска',
  'vehicle_search_page' => 'Страница поиска автомобиля',
  'about_us_page' => 'Страница о нас',
  'store_join_page' => 'Страница присоединения к магазину',
  'deliveryman_join_page' => 'Страница регистрации курьера',
  'terms_and_conditions_page' => 'Страница условий использования',
  'A subscription-based business model allows customers or vendors to access specific features, services, or system functionalities by paying a recurring fee (monthly, quarterly, or yearly). Instead of one-time payments, users remain active as long as their subscription is valid.' => 'Бизнес-модель на основе подписки позволяет клиентам или поставщикам получать доступ к определенным функциям, услугам или функциям системы, внося регулярную плату (ежемесячно, ежеквартально или ежегодно). Вместо разовых платежей пользователи остаются активными до тех пор, пока действительна их подписка.',
  'Provide the port on which the WebSocket server listens' => 'Укажите порт, который прослушивает сервер WebSocket.',
  'Provide the WebSocket server URL used for real-time communication' => 'Укажите URL-адрес сервера WebSocket, используемый для связи в режиме реального времени.',
  'Please_enter_a_valid_WebSocket_URL' => 'Введите действительный URL-адрес WebSocket.',
  'Please enter a valid WebSocket URL' => 'Введите действительный URL-адрес WebSocket.',
  'please_fill_all_required_fields_in_setup_first' => 'Пожалуйста, сначала заполните все обязательные поля в настройке.',
  'Turn ON Ucash payment method' => 'ВКЛЮЧИТЕ способ оплаты Ucash',
  'Place Holder' => 'Место держатель',
  'Input field Data' => 'Поле ввода данных',
  'Specify the payment method name as it will appear in the system' => 'Укажите название способа оплаты так, как оно будет отображаться в системе.',
  'To use offline payments, you need to set up at least one offline payment method' => 'Чтобы использовать офлайн-платежи, вам необходимо настроить хотя бы один офлайн-способ оплаты.',
  'To make available these payment options, you must enable the Offline payment option from' => 'Чтобы сделать доступными эти варианты оплаты, необходимо включить опцию автономной оплаты на странице',
  'In this section, you can add offline payment methods to make them available as offline payment options for the customers' => 'В этом разделе вы можете добавить офлайн-способы оплаты, чтобы сделать их доступными для клиентов в качестве вариантов офлайн-оплаты.',
  'The redirect url field is required when landing integration via is url.' => 'Поле URL-адреса перенаправления необходимо при интеграции целевой страницы через URL-адрес.',
  'Choose the integration method for your custom landing page, then provide the required information.' => 'Выберите метод интеграции для своей целевой страницы, а затем предоставьте необходимую информацию.',
  'Provide the URL of the landing page where users will be redirected' => 'Укажите URL-адрес целевой страницы, на которую будут перенаправлены пользователи.',
  'please_delete_the_existing_landing_page_first' => 'Пожалуйста, сначала удалите существующую целевую страницу.',
  'The file upload must be a file of type: zip.' => 'Загружаемый файл должен быть файлом типа: zip.',
  'Subscription-based model' => 'Модель на основе подписки',
  'Customers place an order using manual payment methods such as bank transfer or mobile banking. Customers must provide a payment reference or proof. Admin or vendor approval may be required before order confirmation.' => 'Клиенты размещают заказ, используя способы оплаты вручную, такие как банковский перевод или мобильный банкинг. Клиенты должны предоставить ссылку на платеж или подтверждение. Перед подтверждением заказа может потребоваться одобрение администратора или поставщика.',
  'This setting allows the admin to set the amount (in the default currency) that a referring customer will earn. The reward is added to their wallet when someone they refer places and completes their first order on the platform.' => 'Этот параметр позволяет администратору установить сумму (в валюте по умолчанию), которую будет зарабатывать приглашающий клиент. Награда добавляется в их кошелек, когда кто-то, кого они пригласили, размещает и выполняет свой первый заказ на платформе.',
  'Admin can define the minimum order amount for the customer to receive free shipping automatically.' => 'Администратор может определить минимальную сумму заказа, при которой покупатель автоматически получит бесплатную доставку.',
  'General Setup is the foundational step, where you configure essential business details (time zone, available currency) to set up the business.' => 'Общая настройка — это основополагающий шаг, на котором вы настраиваете важные сведения о бизнесе (часовой пояс, доступная валюта) для настройки бизнеса.',
  'This address is used to locate the business’s physical location.' => 'Этот адрес используется для определения физического местонахождения компании.',
  'Select your country. This is important for legal, operational, marketing, and payment-related settings.' => 'Выберите свою страну. Это важно для юридических, операционных, маркетинговых и платежных настроек.',
  'Free delivery over ($)' => 'Бесплатная доставка на сумму более ($)',
  'Customers can’t request a Refund if Admin doesn’t specify a cause for Refund. Admin MUST provide a Refund Reason.' => 'Клиенты не могут запросить возврат средств, если администратор не укажет причину возврата. Администратор ДОЛЖЕН указать причину возврата.',
  'Users cannot cancel an order if the Admin does not specify a cause for cancellation even though ' => 'Пользователи не могут отменить заказ, если Администратор не укажет причину отмены, даже если ',
  'Write the related refund reasons that customers must select to request a refund. ' => 'Напишите соответствующие причины возврата, которые клиенты должны выбрать, чтобы запросить возврат средств. ',
  'Refund Settings Guideline' => 'Руководство по настройке возврата',
  'This option enables customers to submit refund requests for their orders. When this option is turned OFF, customers will not be able to request a refund.' => 'Эта опция позволяет клиентам отправлять запросы на возврат средств за свои заказы. Если эта опция отключена, клиенты не смогут запросить возврат средств.',
  'This section allows the admin to manage refund cancellation reasons. Admin can create and configure cancellation reasons and control their active status. Customers will see these reasons as options when they request a refund.' => 'Этот раздел позволяет администратору управлять причинами отмены возврата. Администратор может создавать и настраивать причины отмены и контролировать их активный статус. Клиенты увидят эти причины как варианты, когда запросят возврат средств.',
  '6ammart supports multiple payment methods to provide flexibility and convenience for customers while ensuring smooth transaction management for the platform and vendors.' => '6ammart поддерживает несколько способов оплаты, чтобы обеспечить гибкость и удобство для клиентов, а также обеспечить бесперебойное управление транзакциями для платформы и поставщиков.',
  'Customers pay in cash when they receive their order.' => 'Клиенты платят наличными при получении заказа.',
  'Customers pay online using cards, mobile banking, or digital wallets. Payment is completed before the order is confirmed.' => 'Клиенты платят онлайн с помощью карт, мобильного банкинга или цифровых кошельков. Оплата производится до подтверждения заказа.',
  'Provide a contact phone number so customers and partners can reach your business easily for urgent inquiries, support needs, or quick questions.' => 'Укажите контактный номер телефона, чтобы клиенты и партнеры могли легко связаться с вашей компанией для срочных запросов, поддержки или быстрых вопросов.',
  'Add your company email address. This email is used for business communication and records.' => 'Добавьте адрес электронной почты вашей компании. Этот адрес электронной почты используется для делового общения и записей.',
  'Enter your official company name. This name represents your business and is used across the system.' => 'Введите официальное название вашей компании. Это имя представляет ваш бизнес и используется во всей системе.',
  'Company Name' => 'Название компании',
  'Customer referral earning settings allow you to specify the wallet balance reward that customers will receive for successfully sharing their unique referral code with new customers who then make a purchase.' => 'Настройки заработка по рефералам клиентов позволяют указать вознаграждение на балансе кошелька, которое клиенты получат за успешный обмен своим уникальным реферальным кодом с новыми клиентами, которые затем совершат покупку.',
  'Define how many loyalty points equal 1 unit of currency(Ex: $1 if the system default currency is dollars). It helps customers understand the value of their points when they want to convert them to wallet money.' => 'Определите, сколько баллов лояльности соответствует 1 единице валюты (например: 1 доллар США, если валютой системы по умолчанию являются доллары). Это помогает клиентам понять ценность своих баллов, когда они хотят конвертировать их в деньги кошелька.',
  'Turning on Maintenance mode will temporarily close your online store. Use this when you need to make updates or fix issues.' => 'Включение режима обслуживания временно закроет ваш интернет-магазин. Используйте это, когда вам нужно внести обновления или исправить проблемы.',
  'The smallest amount a customer can add to their wallet at one time.' => 'Наименьшая сумма, которую клиент может пополнить свой кошелек за один раз.',
  'Minimum add Amount' => 'Минимальная сумма добавления',
  'Control vendor-related settings such as:' => 'Управляйте настройками, связанными с поставщиком, такими как:',
  'Store Setup Guideline' => 'Руководство по настройке магазина',
  'Maintenance mode' => 'Режим обслуживания',
  'The Admin Notification Setup allows the administrator to configure how system notifications are sent and managed. Admin notifications can be delivered either manually or through Firebase, depending on the selected configuration.' => 'Настройка уведомлений администратора позволяет администратору настраивать отправку системных уведомлений и управление ими. Уведомления администратора могут доставляться вручную или через Firebase, в зависимости от выбранной конфигурации.',
  'It allows customers to place an order to be delivered to their specific address at a selected time. Delivery is handled by a deliveryman or third-party service. It supports real-time order tracking.' => 'Это позволяет клиентам разместить заказ с доставкой по конкретному адресу в выбранное время. Доставка осуществляется курьером или сторонней службой. Он поддерживает отслеживание заказов в режиме реального времени.',
  'Scheduled' => 'Запланировано',
  'Business Settings Guideline' => 'Руководство по настройке бизнеса',
  'It allows customers to place an order in advance and pick it up directly from the vendor. No delivery charge is applied. The order is prepared for pickup from the vendor.' => 'Это позволяет клиентам разместить заказ заранее и забрать его непосредственно у продавца. Плата за доставку не взимается. Заказ подготовлен к самовывозу у продавца.',
  'It allows customers to place an order and have it delivered to their specified address. Delivery is handled by a deliveryman or third-party service. It supports real-time order tracking.' => 'Это позволяет клиентам разместить заказ и доставить его по указанному адресу. Доставка осуществляется курьером или сторонней службой. Он поддерживает отслеживание заказов в режиме реального времени.',
  'Automated Request' => 'Автоматический запрос',
  'If_you_enable_this_currency,_you_must_active_at_least_one_digital_payment_method_that_supports_this_currency._Otherwise_customers_cannot_pay_via_digital_payments_from_the_app_and_websites._And_Also_stores_cannot_pay_you_digitally' => 'Если вы включите эту валюту, вы должны активировать хотя бы один цифровой способ оплаты, поддерживающий эту валюту. В противном случае клиенты не смогут платить с помощью цифровых платежей из приложения и веб-сайтов. А также магазины не могут платить вам в цифровом виде',
  'store Details' => 'Детали магазина',
  'store List' => 'Список магазинов',
  'To set different commission for commission based stores.' => 'Установить разную комиссию для комиссионных магазинов.',
  'By selecting commission based business model stores can run business with you based on commission based payment per order.' => 'Выбрав комиссионную бизнес-модель, магазины могут вести с вами бизнес на основе комиссионной оплаты за заказ.',
  'By selecting subscription based business model stores can run business with you based on subscription package.' => 'Выбрав бизнес-модель на основе подписки, магазины могут вести бизнес с вами на основе пакета подписки.',
  'Setup your business model from here' => 'Настройте свою бизнес-модель здесь',
  'Manual Request' => 'Ручной запрос',
  'If this option is enabled, customers can add money to their wallet using digital payment methods like bank transfer, mobile wallets, etc.' => 'Если эта опция включена, клиенты могут добавлять деньги в свой кошелек, используя цифровые способы оплаты, такие как банковский перевод, мобильные кошельки и т. д.',
  'This feature allows customers to place orders based on how they want to receive or consume their items.' => 'Эта функция позволяет клиентам размещать заказы в зависимости от того, как они хотят получать или потреблять свои товары.',
  'Order Settings Guideline' => 'Руководство по настройке заказа',
  'The private key field is required when status is 1.' => 'Поле закрытого ключа является обязательным, если статус равен 1.',
  'Active at least one gateway that support your currency. To change currency setup visit' => 'Активируйте хотя бы один шлюз, поддерживающий вашу валюту. Чтобы изменить настройку валюты, посетите',
  'Public Key is required' => 'Требуется открытый ключ',
  'Client Secret is required' => 'Требуется секрет клиента.',
  'Merchant Website Link is required when payment status is ON' => 'Ссылка на веб-сайт продавца обязательна, когда статус платежа включен.',
  'Merchant Id is required when payment status is ON' => 'Идентификатор продавца требуется, когда статус платежа включен.',
  'Add funds to wallet' => 'Пополнить кошелек',
  'order_is_picked_up' => 'Заказ забран',
  'Please_send_a_Feedback' => 'Пожалуйста, отправьте отзыв',
  'Dear' => 'Дорогой',
  'Mail_Body' => 'Тело письма',
  'The return otp field is required.' => 'Поле возврата ОТП является обязательным.',
  'The order id field is required.' => 'Поле идентификатора заказа является обязательным.',
  'This setting allows the admin to set the amount (in the default currency) that a referring deliveryman will earn. The reward is added to their wallet when someone they refer places and completes their registration on the platform.' => 'Этот параметр позволяет администратору установить сумму (в валюте по умолчанию), которую будет зарабатывать приглашающий курьер. Награда добавляется в их кошелек, когда кто-то, кого они пригласили, размещает и завершает регистрацию на платформе.',
  'Deliveryman referral earning settings allow you to specify the wallet balance reward that the deliveryman will receive for successfully sharing their unique referral code with a new deliveryman for registration.' => 'Настройки заработка по рефералам доставщика позволяют вам указать вознаграждение на балансе кошелька, которое доставщик получит за успешную передачу своего уникального реферального кода новому доставщику для регистрации.',
  'Minimum Point Required to Convert: This setup is for inserting the minimum number of points a deliveryman must have to convert points into a wallet balance.' => 'Минимальное количество баллов, необходимое для конвертации: эта настройка предназначена для вставки минимального количества баллов, которое должен иметь курьер, чтобы конвертировать баллы в баланс кошелька.',
  '$1.00 Equivalent to Points: This section is for calculating the wallet value of loyalty points when converting' => 'Эквивалент 1,00 доллара США в баллах. Этот раздел предназначен для расчета стоимости баллов лояльности в кошельке при конвертации.',
  'Loyalty Points earn per order: this setup is for setting the value of how much the deliveryman will earn when completing the delivery' => 'Баллы лояльности начисляются за заказ: эта настройка предназначена для установки суммы, которую курьер заработает при выполнении доставки.',
  'You_can_return_only_canceled_parcel_orders' => 'Вы можете вернуть только отмененные заказы на посылки.',
  'Invalid_return_otp' => 'Неверный ответный код возврата',
  'Allowing the option that deliverymen will get points when they complete the order delivery successfully.' => 'Предоставление возможности получать баллы курьерам при успешном завершении доставки заказа.',
  'Loyalty Point Setup' => 'Настройка баллов лояльности',
  'Create and manage predefined messages that customers can choose when reporting an issue. You can activate or deactivate each message as needed.' => 'Создавайте предопределенные сообщения, которые клиенты могут выбирать при сообщении о проблеме, и управляйте ими. При необходимости вы можете активировать или деактивировать каждое сообщение.',
  'The coordinates field is required.' => 'Поле координат является обязательным.',
  'Invalid delivery charge configuration for module:' => 'Неверная конфигурация стоимости доставки для модуля:',
  'reload_page' => 'Обновить страницу',
  '500_warning_message' => '500 предупреждающее сообщение',
  'remove_sub_categories_first' => 'Сначала удалите подкатегории',
  'jpeg, jpg, png, gif, webp Less Than 2MB' => 'Jpeg, jpg, png, gif, webp Менее 2 МБ',
  'invalid_file_type' => 'Неверный тип файла',
  'please_select_image' => 'Пожалуйста, выберите изображение',
  'ubill_ge' => 'Убилльге',
  'The login type field is required.' => 'Поле типа входа является обязательным.',
  'The selected login type is invalid.' => 'Выбранный тип входа недействителен.',
  'აფთიაქი' => 'აფთიაქი',
  'მარკეტები' => 'მარკეტები',
  'Cash-in-hand control allows the platform to monitor and limit the amount of cash collected by deliverymen from Cash on Delivery (COD) orders. This feature helps reduce financial risk and ensures timely settlement between the deliveryman and the platform.' => 'Контроль наличности позволяет платформе отслеживать и ограничивать сумму денежных средств, получаемых курьерами за заказы наложенным платежом (COD). Эта функция помогает снизить финансовый риск и обеспечивает своевременный расчет между курьером и платформой.',
  'Cash-in-Hand Controls' => 'Наличный контроль',
  'When the wallet feature is enabled, customers can use their wallet balance to pay for orders. Refunds can also be sent directly to the wallet of the customer for easy use in future purchases.' => 'Когда функция кошелька включена, клиенты могут использовать баланс своего кошелька для оплаты заказов. Возврат средств также может быть отправлен непосредственно на кошелек клиента для удобства использования при будущих покупках.',
  'When Custom Sorting is selected, the system applies the chosen sorting rule dynamically to display items, categories, and subcategories accordingly.' => 'Если выбрана пользовательская сортировка, система динамически применяет выбранное правило сортировки для соответствующего отображения элементов, категорий и подкатегорий.',
  'Manage and configure how vendors & deliverymen receive their payouts' => 'Управляйте и настраивайте способы получения выплат поставщиками и курьерами.',
  'Automated Message Guideline' => 'Руководство по автоматическим сообщениям',
  'PHP file size no more than :size MB' => 'Размер файла PHP не более :size МБ',
  'want_to_Turn_OFF_the_React_Website_addon?' => 'Хотите отключить дополнение React Website?',
  'want_to_Turn_ON_the_React_Website_addon?' => 'Хотите ВКЛЮЧИТЬ дополнение React Website?',
  'want_to_Turn_OFF_the_Vendor_App_addon?' => 'Хотите отключить дополнение Vendor App?',
  'want_to_Turn_ON_the_Vendor_App_addon?' => 'Хотите ВКЛЮЧИТЬ дополнение Vendor App?',
  'Delivery photo is required as proof' => 'В качестве доказательства необходимо предоставить фото доставки.',
  'Deliverymen can see their earnings' => 'Доставщики могут видеть свои доходы',
  'The Deliveryman App Setup helps the admin adjust crucial settings for deliverymen’s app usage. You can control: ' => 'Настройка приложения Deliveryman помогает администратору настроить важные параметры использования приложения доставщиками. Вы можете контролировать: ',
  'Allowing tips from customers' => 'Разрешить чаевые от клиентов',
  'Maximum number of active orders' => 'Максимальное количество активных ордеров',
  'deliveryman_deleted_successfully' => 'Доставщик успешно удален',
  'deliveryman_referral_bonus' => 'Реферальный бонус доставщика',
  'Help & Support Page' => 'Страница справки и поддержки',
  'Store added to favorites' => 'Магазин добавлен в избранное',
  'Store removed from favorites' => 'Магазин удален из избранного',
  'Item added to favorites' => 'Товар добавлен в избранное',
  'Item removed from favorites' => 'Товар удален из избранного',
  'Client Secret is required when payment status is ON' => 'Секрет клиента требуется, когда статус платежа включен.',
  'Sent_notification_on_deliveryman_referral_bonus' => 'Отправлено уведомление о реферальном бонусе курьеру',
  'საკვები' => 'საკვები',
  'ტექნიკა' => 'ტექნიკა',
  'ლუდი' => 'ლუდი',
